const SEQ=[{topic:"2.1",type:"SEQ",q:"Terangkan maksud pharmacology dan beza pharmacodynamics dengan pharmacokinetics.",answer:"Pharmacology ialah kajian/sains tentang ubat, tindakan, penggunaan dan kesannya. Pharmacodynamics ialah apa yang ubat lakukan kepada badan; pharmacokinetics ialah apa yang badan lakukan kepada ubat.",p:100,official:true},
{topic:"2.1",type:"SEQ",q:"Senaraikan empat proses utama pharmacokinetics.",answer:"Absorption, distribution, metabolism dan excretion.",p:100,official:true},
{topic:"2.2",type:"SEQ",q:"Nyatakan lima sumber semula jadi ubat yang terdapat dalam nota.",answer:"Plant, animal, mineral, microorganism dan human.",p:100,official:true},
{topic:"2.2",type:"SEQ",q:"Bezakan sekurang-kurangnya empat tujuan penggunaan ubat.",answer:"Contoh: symptomatic, preventive, diagnostic, curative, health maintenance, contraceptive dan replacement.",p:100,official:true},
{topic:"2.3",type:"SEQ",q:"Bezakan tablet, capsule, suspension dan emulsion.",answer:"Tablet ialah sediaan pepejal; capsule mempunyai cangkerang gelatin; suspension mempunyai zarah pepejal tersebar dalam cecair; emulsion ialah campuran dua cecair yang tidak bercampur.",p:100,official:false},
{topic:"2.4",type:"SEQ",q:"Jelaskan mengapa route sublingual boleh memintas first-pass metabolism.",answer:"Tisu sublingual sangat vascularized dan ubat diserap melalui laluan oral yang membolehkan ia memintas laluan GI/portal yang menyebabkan first-pass metabolism.",p:100,official:false},
{topic:"2.4",type:"SEQ",q:"Terangkan maksud onset, peak dan duration.",answer:"Onset ialah masa sehingga kesan mula berlaku; peak ialah ketika kesan mencapai tahap maksimum; duration ialah tempoh kesan ubat.",p:100,official:false},
{topic:"2.5",type:"SEQ",q:"Bezakan therapeutic effect, side effect, adverse effect dan toxicity.",answer:"Therapeutic ialah kesan dikehendaki; side effect ialah kesan tidak diingini yang boleh berlaku; adverse effect ialah kesan tidak diingini/berbahaya; toxicity ialah kesan berbahaya akibat ketoksikan ubat.",p:100,official:false},
{topic:"2.6",type:"SEQ",q:"Nyatakan faktor dalaman dan luaran yang boleh mempengaruhi tindakan ubat.",answer:"Dalaman: umur, berat, sex, psychological, physiological/pathological dan genetic/cultural/racial. Luaran: ubat/suplemen/herba lain, adherence, route/time, storage serta drug-drug/food/disease interactions.",p:100,official:false},
{topic:"2.6",type:"SEQ",q:"Beri dua contoh interaksi yang disebut dalam nota dan jelaskan kepentingannya.",answer:"Contoh grapefruit dengan ubat tertentu; vitamin K vegetables dengan warfarin; beta blocker/metoprolol dengan asthma/hypoglycemia. Interaksi boleh mengubah keberkesanan atau keselamatan ubat.",p:100,official:false},
{topic:"2.7",type:"SEQ",q:"Bezakan bactericidal dan bacteriostatic serta jelaskan isu resistance.",answer:"Bactericidal membunuh bakteria; bacteriostatic menghalang pembiakan. Penggunaan antibiotik yang salah boleh menyumbang kepada resistance.",p:100,official:false},
{topic:"2.7",type:"SEQ",q:"Terangkan perkara penting ketika memberi digoxin berdasarkan nota.",answer:"Periksa apex beat; jangan beri jika kurang daripada 60 bpm seperti dinyatakan dalam nota dan pantau tanda toxicity.",p:100,official:false},
{topic:"2.8",type:"SEQ",q:"Terangkan keperluan penyimpanan dan kawalan stok dangerous drugs.",answer:"Simpan dalam ruang berkunci/kawalan berganda mengikut polisi; kunci dikawal; stok diperiksa setiap shift seperti nota; semak expiry/warna dan asingkan penyimpanan mengikut kategori serta label yang jelas.",p:100,official:false},
{topic:"2.8",type:"SEQ",q:"Apakah semakan penting sebelum pemberian dangerous drug?",answer:"Semak patient, prescription, registration, dose, time, route dan witness; rekod segera dalam DDA book/BHT/chart dan pastikan stock balance/signature.",p:100,official:false},
{topic:"2.9",type:"SEQ",q:"Jelaskan autonomy, beneficence, nonmaleficence, justice dan veracity.",answer:"Autonomy ialah hak membuat keputusan; beneficence berbuat baik; nonmaleficence mengelakkan kemudaratan; justice keadilan; veracity berkata benar.",p:100,official:false},
{topic:"2.9",type:"SEQ",q:"Nyatakan elemen utama malpractice.",answer:"Duty, breach of duty, causal connection dan damage.",p:100,official:false},
{topic:"2.10",type:"SEQ",q:"Senaraikan 7R dan tiga tambahan dalam 10R.",answer:"7R: Right Patient, Medication, Dose, Route, Time, To Refuse, Documentation. Tambahan: Right Assessment, Right Evaluation, Right Client Education.",p:100,official:false},
{topic:"2.11.1",type:"SEQ",q:"Terangkan prinsip asas penyediaan dan pemberian ubat oral yang selamat.",answer:"Sediakan di kawasan bersih/terang, semak label dan identiti pesakit, ikut prinsip keselamatan, pastikan ubat diambil/ditelan mengikut keadaan dan dokumentasikan dengan tepat.",p:100,official:false},
{topic:"2.11.2",type:"SEQ",q:"Bandingkan ID, SC, IM dan IV dari segi tissue dan sudut.",answer:"ID: dermis, 5–15°; SC: subcutaneous tissue, 45°/90° jika tisu tebal; IM: muscle, 90°; IV: vein, 15–30° mengikut teknik.",p:100,official:false},
{topic:"2.11.2",type:"SEQ",q:"Terangkan langkah keselamatan utama dalam pemberian IM dan tindakan jika darah muncul semasa aspirasi seperti dalam nota.",answer:"Pilih site dan tissue betul, lakukan asepsis, gunakan sudut 90°, masukkan needle dengan stabil, aspirasi 0.3–0.5 mL seperti nota. Jika darah muncul, hentikan, keluarkan needle dan gunakan ubat/needle baharu mengikut prosedur.",p:100,official:false}];
const CRISIS=[{topic:"2.1",type:"CRISIS",q:"Crisis: Ubat diberikan tetapi pesakit menunjukkan kesan luar biasa. Kenal pasti bidang pharmacology yang perlu digunakan dan tindakan penilaian awal.",answer:"Kenal pasti unwanted/adverse/toxic effect; assess pesakit dan keadaan klinikal.",p:75},
{topic:"2.2",type:"CRISIS",q:"Crisis: Pesakit bertanya mengapa ubat diberi sedangkan dia tiada simptom. Tentukan jenis drug use yang mungkin.",answer:"Preventive, diagnostic, health maintenance, replacement atau tujuan lain bergantung pada kes.",p:75},
{topic:"2.3",type:"CRISIS",q:"Crisis: Pesakit menghancurkan semua tablet termasuk slow-release. Apa risiko keselamatan yang perlu dikenal pasti?",answer:"Jangan hancurkan slow-release/enteric-coated sewenang-wenangnya; semak jenis sediaan dan arahan.",p:75},
{topic:"2.4",type:"CRISIS",q:"Battle: Susun kad ADME yang bercampur kepada urutan betul dan pertahankan jawapan dalam 30 saat.",answer:"Absorption → Distribution → Metabolism → Excretion.",p:75},
{topic:"2.5",type:"CRISIS",q:"Crisis: Pesakit mengalami reaksi yang tidak diingini. Bezakan side effect dengan adverse effect/toxicity berdasarkan maklumat klinikal yang diberi.",answer:"Klasifikasikan berdasarkan sifat dan tahap kesan; jangan label tanpa assessment.",p:75},
{topic:"2.6",type:"CRISIS",q:"Crisis: Pesakit mengambil warfarin dan mengubah diet secara mendadak dengan banyak sayuran tinggi vitamin K. Apakah isu?",answer:"Drug-food interaction; perlu perhatian terhadap perubahan vitamin K dan pengurusan yang sesuai.",p:75},
{topic:"2.6",type:"CRISIS",q:"Battle: Pesakit mengambil beberapa ubat, suplemen dan herba. Apakah faktor luaran perlu disemak?",answer:"Other medicines/supplements/traditional/herbal, adherence, route/time, storage dan interactions.",p:75},
{topic:"2.7",type:"CRISIS",q:"Crisis: Pesakit meminta antibiotik untuk penyakit virus. Defend your decision.",answer:"Antibiotics digunakan untuk bakteria, bukan virus; elakkan penggunaan tidak sesuai dan resistance.",p:75},
{topic:"2.7",type:"CRISIS",q:"Battle: Apex beat pesakit sebelum digoxin ialah 56 bpm. Apa tindakan?",answer:"Jangan beri digoxin berdasarkan nota; semak/ambil tindakan mengikut arahan dan polisi klinikal.",p:75},
{topic:"2.8",type:"CRISIS",q:"Crisis: Rekod DDA tidak seimbang selepas satu dose. Apakah yang perlu dilakukan?",answer:"Semak rekod, prescription, dose, patient, witness, stock balance dan laporkan/urus mengikut polisi; jangan ubah rekod secara tidak sah.",p:75},
{topic:"2.8",type:"CRISIS",q:"Battle: Kunci ruang DDA ditinggalkan di tempat terbuka. Kenal pasti risiko utama.",answer:"Pelanggaran kawalan akses/storage dangerous drugs; amankan dan laporkan mengikut polisi.",p:75},
{topic:"2.9",type:"CRISIS",q:"Crisis: Pesakit kompeten berkata tidak mahu mengambil ubat. Apakah prinsip dan tindakan?",answer:"Autonomy/Right To Refuse; dengar sebab, beri penjelasan sesuai, hormati keputusan dan dokumentasikan.",p:75},
{topic:"2.9",type:"CRISIS",q:"Battle: Cari empat unsur malpractice daripada satu kes yang diberikan pengajar.",answer:"Duty, breach, causal connection dan damage.",p:75},
{topic:"2.10",type:"CRISIS",q:"Crisis: Order ubat lengkap tetapi tiada assessment yang relevan. R 10R manakah perlu diperiksa?",answer:"Right Assessment dan keselamatan keseluruhan sebelum pemberian.",p:75},
{topic:"2.10",type:"CRISIS",q:"Battle: Pesakit meminta hak untuk menolak ubat tetapi staf terus memaksa. Kenal pasti pelanggaran.",answer:"Right To Refuse/autonomy dan isu etika.",p:75},
{topic:"2.11.1",type:"CRISIS",q:"Crisis: Kawasan medication preparation gelap dan banyak gangguan. Apa risiko dan tindakan?",answer:"Risiko medication error; gunakan kawasan bersih, terang dan kurang gangguan.",p:75},
{topic:"2.11.2",type:"CRISIS",q:"Crisis: Suntikan yang sepatutnya IM disediakan pada 45°. Apa komponen yang perlu disemak?",answer:"Route, target tissue dan angle; IM dalam nota ialah muscle dan 90°.",p:75},
{topic:"2.11.3",type:"CRISIS",q:"Battle: Pelajar meletakkan eye drop terus pada cornea. Betulkan teknik asas.",answer:"Eye drops diletakkan pada conjunctiva, bukan cornea.",p:75},
{topic:"2.11.4",type:"CRISIS",q:"Crisis: Ubat tidak diberi kerana pesakit muntah tetapi chart ditanda sebagai diberi. Apakah masalah?",answer:"Documentation error; rekod perlu tepat, lengkap, tepat masa dan objektif.",p:75},
{topic:"3.0",type:"CRISIS",q:"Crisis: Pesakit mahu menggantikan rawatan konvensional sepenuhnya dengan T&CM. Apakah beza complementary vs alternative dan isu rujukan?",answer:"Complementary digunakan bersama rawatan konvensional; alternative menggantikan. Perlu pertimbangkan keselamatan, etika dan rujukan sesuai.",p:75}];
const BOSSES=[{id:"BOSS 01",title:"Medication Safety Mega Mission",brief:"Kes: pesakit menerima ubat dan menunjukkan simptom tidak normal. Team mesti kenal pasti masalah, semak 10R, tentukan tindakan, semak interaction/route/dose/timing dan dokumentasi. 90 saat.",p:250},
{id:"BOSS 02",title:"The ADME Tower",brief:"Susun dan terangkan ADME, kemudian beri satu contoh route yang boleh memintas first-pass. 60 saat.",p:250},
{id:"BOSS 03",title:"Parenteral Arena",brief:"Bandingkan ID/SC/IM/IV: tissue, angle, site dan contoh kegunaan. Kemudian jawab satu situasi pemilihan route. 90 saat.",p:250},
{id:"BOSS 04",title:"DDA Vault",brief:"Kes dangerous drug: semak prescription, patient, dose, route, time, witness, storage, stock dan record. Team perlu defend setiap langkah. 90 saat.",p:250},
{id:"BOSS 05",title:"Ethics Tribunal",brief:"Pesakit kompeten refuse medication. Team perlu gunakan autonomy, Right To Refuse, beneficence, nonmaleficence dan documentation. 90 saat.",p:250},
{id:"BOSS 06",title:"Antibiotic Siege",brief:"Bezakan bactericidal/bacteriostatic, bakteria vs virus, resistance dan kepentingan C&S/complete course seperti dalam nota. 60 saat.",p:250},
{id:"BOSS 07",title:"Documentation Dungeon",brief:"Kes: ubat tidak diberi kerana muntah tetapi rekod salah. Team perlu membetulkan prinsip dokumentasi dan terangkan audit trail. 60 saat.",p:250},
{id:"BOSS 08",title:"Patient Education Raid",brief:"Team perlu educate pesakit tentang nama, tujuan, dos, cara/waktu, side effects, adherence, storage, expired medicines, sedation dan follow-up. 90 saat.",p:250},
{id:"BOSS 09",title:"Interaction Labyrinth",brief:"Kes pesakit mengambil grapefruit, warfarin + vitamin K-rich vegetables dan beberapa ubat/suplemen. Kenal pasti interaction yang berkaitan dan risiko keselamatan. 90 saat.",p:250},
{id:"BOSS 10",title:"Final Pharmacology Nexus",brief:"Gabungkan 2.1–3.0: definitions, ADME, effects, factors, classification, DDA, ethics, 10R, oral/parenteral/other routes, documentation, education dan T&CM. Setiap team pilih strategi dan defend keputusan klinikal. 120 saat.",p:250}];
const DOPS=[{title:"DOPS 1 — Safe Oral Medication Administration",topic:"2.11.1",brief:"Demonstrasi penyediaan dan pemberian ubat oral: kawasan bersih/terang, semakan label dan pesakit, prinsip keselamatan, pemerhatian pengambilan/menelan dan dokumentasi.",tag:"JSU official DOPS",p:200},
{title:"DOPS 2 — Parenteral Medication Administration",topic:"2.11.2",brief:"Demonstrasi parenteral berdasarkan route/site/tissue/angle/asepsis/safety/documentation. Penilaian sebenar mesti di bawah penyeliaan pengajar dan SOP/kompetensi institusi.",tag:"JSU official DOPS",p:200}];
function now(){return Date.now()/1000}
function json(x,s=200){return new Response(JSON.stringify(x),{status:s,headers:{"content-type":"application/json;charset=utf-8","cache-control":"no-store"}})}
async function init(db){await db.batch([
db.prepare(`CREATE TABLE IF NOT EXISTS app_state(id INTEGER PRIMARY KEY,started INTEGER DEFAULT 0,phase TEXT DEFAULT 'lobby',item_index INTEGER DEFAULT 0,timer_end REAL DEFAULT 0,last_event TEXT DEFAULT 'Room ready',mode TEXT DEFAULT 'MCQ')`),
db.prepare(`CREATE TABLE IF NOT EXISTS teams(team TEXT PRIMARY KEY,name TEXT,color TEXT,hp INTEGER DEFAULT 1000,xp INTEGER DEFAULT 0,coins INTEGER DEFAULT 0)`),
db.prepare(`CREATE TABLE IF NOT EXISTS players(id TEXT PRIMARY KEY,name TEXT,team TEXT,joined REAL)`),
db.prepare(`CREATE TABLE IF NOT EXISTS answers(item_key TEXT,player_id TEXT,correct INTEGER,points INTEGER,response TEXT,timestamp REAL,question TEXT,topic TEXT,type TEXT,student TEXT,team TEXT,gm_mark TEXT DEFAULT '',PRIMARY KEY(item_key,player_id))`),
db.prepare(`CREATE TABLE IF NOT EXISTS boss_scores(id INTEGER PRIMARY KEY AUTOINCREMENT,boss_index INTEGER,team TEXT,points INTEGER,notes TEXT,timestamp REAL)`),
db.prepare(`INSERT OR IGNORE INTO app_state(id) VALUES(1)`),
...TEAM_CODES.map((t,i)=>db.prepare(`INSERT OR IGNORE INTO teams VALUES(?,?,?,?,?,?)`).bind(t,`TEAM ${t}`,TEAM_COLORS[i],1000,0,0))
])}
async function meta(db){return db.prepare(`SELECT * FROM app_state WHERE id=1`).first()}
async function currentItem(db,m){
if(m.phase==='dops')return {...DOPS[m.item_index%DOPS.length],type:'DOPS',key:`DOPS:${m.item_index}`};
if(m.phase==='crisis')return {...CRISIS[m.item_index%CRISIS.length],key:`CRISIS:${m.item_index}`};
if(m.phase==='boss')return {...BOSSES[m.item_index%BOSSES.length],type:'BOSS',topic:'FINAL',key:`BOSS:${m.item_index}`};
if(m.mode==='SEQ')return {...SEQ[m.item_index%SEQ.length],key:`SEQ:${m.item_index}`};
return {...MCQ[m.item_index%MCQ.length],key:`MCQ:${m.item_index}`};
}
async function state(db){
const m=await meta(db),ts=await db.prepare(`SELECT * FROM teams ORDER BY team`).all(),ps=await db.prepare(`SELECT * FROM players ORDER BY joined`).all();
const teams={};for(const t of ts.results||[])teams[t.team]={name:t.name,color:t.color,hp:t.hp,xp:t.xp,coins:t.coins,players:[]};
const players={};for(const p of ps.results||[]){players[p.id]={name:p.name,team:p.team,joined:p.joined};if(teams[p.team])teams[p.team].players.push(p.id)}
return {started:!!m.started,phase:m.phase,mode:m.mode,item_index:m.item_index,timer_end:m.timer_end,teams,players,last_event:m.last_event,current:await currentItem(db,m)}}
async function countAnswers(db,key){let r=await db.prepare(`SELECT COUNT(*) n FROM answers WHERE item_key=?`).bind(key).first();return +r.n}
async function advance(db){let m=await meta(db);
if(m.mode==='MCQ'){if(m.item_index<MCQ.length-1)return db.prepare(`UPDATE app_state SET item_index=item_index+1,last_event=? WHERE id=1`).bind(`MCQ ${m.item_index+2}/${MCQ.length}`).run();return db.prepare(`UPDATE app_state SET mode='SEQ',item_index=0,last_event='80 MCQ selesai — 20 SEQ bermula' WHERE id=1`).run();}
if(m.mode==='SEQ'){if(m.item_index<SEQ.length-1)return db.prepare(`UPDATE app_state SET item_index=item_index+1,last_event=? WHERE id=1`).bind(`SEQ ${m.item_index+2}/${SEQ.length}`).run();return db.prepare(`UPDATE app_state SET phase='crisis',mode='CRISIS',item_index=0,last_event='20 SEQ selesai — CRISIS ARENA dibuka' WHERE id=1`).run();}
if(m.phase==='crisis'){if(m.item_index<CRISIS.length-1)return db.prepare(`UPDATE app_state SET item_index=item_index+1,last_event=? WHERE id=1`).bind(`CRISIS ${m.item_index+2}/${CRISIS.length}`).run();return db.prepare(`UPDATE app_state SET phase='dops',mode='DOPS',item_index=0,last_event='CRISIS selesai — DOPS ARENA dibuka' WHERE id=1`).run();}
if(m.phase==='dops'){if(m.item_index<DOPS.length-1)return db.prepare(`UPDATE app_state SET item_index=item_index+1,last_event='Next DOPS' WHERE id=1`).run();return db.prepare(`UPDATE app_state SET phase='boss',mode='BOSS',item_index=0,last_event='DOPS selesai — FINAL BOSS dibuka' WHERE id=1`).run();}
if(m.phase==='boss'){if(m.item_index<BOSSES.length-1)return db.prepare(`UPDATE app_state SET item_index=item_index+1,last_event='Next FINAL BOSS' WHERE id=1`).run();return db.prepare(`UPDATE app_state SET phase='complete',last_event='PHARMACOLOGY LEGENDS COMPLETE!' WHERE id=1`).run();}}
const INDEX_B64 = "";
function indexResponse(){
  const bin = atob(INDEX_B64);
  const bytes = new Uint8Array(bin.length);
  for(let i=0;i<bin.length;i++) bytes[i]=bin.charCodeAt(i);
  return new Response(bytes,{headers:{"content-type":"text/html;charset=utf-8","cache-control":"no-store"}});
}
async function handler(req,env){
if(!env.DB)return json({error:"D1 belum disambungkan."},503);await init(env.DB);const u=new URL(req.url),p=u.pathname;
if(req.method==="GET"){
if(p==="/api/state")return json(await state(env.DB));
if(p==="/api/item"){let m=await meta(env.DB);return json(await currentItem(env.DB,m))}
if(p==="/api/report.csv"){let r=await env.DB.prepare(`SELECT topic,type,question,student,team,correct,points,response,gm_mark,timestamp FROM answers ORDER BY timestamp`).all();let rows=[["Topic","Type","Question","Student","Team","Correct","Points","Response","GM Mark","Timestamp"],...(r.results||[]).map(x=>[x.topic,x.type,x.question,x.student,x.team,x.correct?"YES":"NO",x.points,x.response||"",x.gm_mark||"",new Date(x.timestamp*1000).toLocaleString("ms-MY")])];let csv=rows.map(a=>a.map(v=>`"${String(v??"").replaceAll('"','""')}"`).join(",")).join("\n");return new Response("\ufeff"+csv,{headers:{"content-type":"text/csv;charset=utf-8","content-disposition":"attachment; filename=pharmacology_legends_v3_report.csv"}})}
if(p==="/api/boss-report.csv"){let r=await env.DB.prepare(`SELECT * FROM boss_scores ORDER BY timestamp`).all();let rows=[["Boss","Team","Points","Notes","Timestamp"],...(r.results||[]).map(x=>[x.boss_index,x.team,x.points,x.notes,new Date(x.timestamp*1000).toLocaleString("ms-MY")])];let csv=rows.map(a=>a.map(v=>`"${String(v??"").replaceAll('"','""')}"`).join(",")).join("\n");return new Response("\ufeff"+csv,{headers:{"content-type":"text/csv"}})} 
if(p==="/"||p==="/index.html")return indexResponse();return new Response("Not found",{status:404})}
let b={};try{b=await req.json()}catch{}
if(p==="/api/join"){let name=String(b.name||"Player").trim().slice(0,30)||"Player",team=TEAM_CODES.includes(String(b.team))?String(b.team):"A",pid=String(b.player_id||crypto.randomUUID());let c=await env.DB.prepare(`SELECT COUNT(*) n FROM players WHERE team=?`).bind(team).first();if(+c.n>=10)return json({error:`Team ${team} sudah penuh (10 orang).`},409);await env.DB.batch([env.DB.prepare(`DELETE FROM players WHERE id=?`).bind(pid),env.DB.prepare(`INSERT INTO players VALUES(?,?,?,?)`).bind(pid,name,team,now()),env.DB.prepare(`UPDATE app_state SET last_event=? WHERE id=1`).bind(`${name} masuk Team ${team}`)]);return json({player_id:pid,state:await state(env.DB)})}
if(p==="/api/start"){await env.DB.batch([env.DB.prepare(`DELETE FROM answers`),env.DB.prepare(`DELETE FROM boss_scores`),env.DB.prepare(`UPDATE teams SET hp=1000,xp=0,coins=0`),env.DB.prepare(`UPDATE app_state SET started=1,phase='topic',mode='MCQ',item_index=0,timer_end=0,last_event='BATTLE STARTED — 80 MCQ + 20 SEQ' WHERE id=1`)]);return json(await state(env.DB))}
if(p==="/api/next"){let m=await meta(env.DB),it=await currentItem(env.DB,m),pc=await env.DB.prepare(`SELECT COUNT(*) n FROM players`).first();if(['MCQ','SEQ'].includes(m.mode)&&+pc.n){let n=await countAnswers(env.DB,it.key);if(n<+pc.n)return json({error:`Belum semua pemain submit. ${n}/${pc.n}.`},409)}await advance(env.DB);return json(await state(env.DB))}
if(p==="/api/answer"){let pid=String(b.player_id||""),pl=await env.DB.prepare(`SELECT * FROM players WHERE id=?`).bind(pid).first();if(!pl)return json({error:"Player belum join."},400);let m=await meta(env.DB),it=await currentItem(env.DB,m);if(!['MCQ','SEQ'].includes(it.type))return json({error:"Item ini dinilai oleh Game Master."},400);if(await env.DB.prepare(`SELECT 1 FROM answers WHERE item_key=? AND player_id=?`).bind(it.key,pid).first())return json({error:"Anda sudah submit item ini."},409);let correct=false,pts=0,response=String(b.response||"");if(it.type==='MCQ'){correct=Number(b.choice)===it.c;pts=correct?it.p:0}else pts=0;await env.DB.prepare(`INSERT INTO answers VALUES(?,?,?,?,?,?,?,?,?,?,?,?)`).bind(it.key,pid,correct?1:0,pts,response,now(),it.q,it.topic,it.type,pl.name,pl.team,'').run();if(pts>0)await env.DB.prepare(`UPDATE teams SET xp=xp+?,coins=coins+20 WHERE team=?`).bind(pts,pl.team).run();else if(it.type==='MCQ')await env.DB.prepare(`UPDATE teams SET hp=MAX(0,hp-30) WHERE team=?`).bind(pl.team).run();await env.DB.prepare(`UPDATE app_state SET last_event=? WHERE id=1`).bind(`${pl.name} — ${it.type} submitted — Team ${pl.team}`).run();return json(await state(env.DB))}
if(p==="/api/mark-seq"){let m=await meta(env.DB),it=await currentItem(env.DB,m);if(it.type!=='SEQ')return json({error:"Bukan SEQ."},400);let pid=String(b.player_id||""),points=Math.max(0,Math.min(100,Number(b.points||0))),mark=String(b.mark||"").slice(0,30);let r=await env.DB.prepare(`UPDATE answers SET points=?,correct=?,gm_mark=? WHERE item_key=? AND player_id=?`).bind(points,points>=70,mark,it.key,pid).run();if(!Number(r.meta?.changes))return json({error:"Submission tidak dijumpai."},404);let rows=await env.DB.prepare(`SELECT team,COALESCE(SUM(points),0) xp FROM answers GROUP BY team`).all();await env.DB.batch((rows.results||[]).map(x=>env.DB.prepare(`UPDATE teams SET xp=? WHERE team=?`).bind(x.xp,x.team)));return json(await state(env.DB))}
if(p==="/api/crisis-score"){let m=await meta(env.DB);if(m.phase!=='crisis')return json({error:"Bukan Crisis Arena."},400);let team=String(b.team||"");if(!TEAM_CODES.includes(team))return json({error:"Team tidak sah."},400);let points=Math.max(0,Math.min(100,Number(b.points||0)));await env.DB.prepare(`UPDATE teams SET xp=xp+?,coins=coins+? WHERE team=?`).bind(points,Math.floor(points/10),team).run();await env.DB.prepare(`UPDATE app_state SET last_event=? WHERE id=1`).bind(`🚨 CRISIS Team ${team} +${points} XP`).run();return json(await state(env.DB))}
if(p==="/api/dops-score"){let m=await meta(env.DB);if(m.phase!=='dops')return json({error:"Bukan DOPS Arena."},400);let team=String(b.team||"");if(!TEAM_CODES.includes(team))return json({error:"Team tidak sah."},400);let points=Math.max(0,Math.min(200,Number(b.points||0)));await env.DB.prepare(`UPDATE teams SET xp=xp+?,coins=coins+? WHERE team=?`).bind(points,Math.floor(points/20),team).run();await env.DB.prepare(`UPDATE app_state SET last_event=? WHERE id=1`).bind(`💉 DOPS Team ${team} +${points} XP`).run();return json(await state(env.DB))}
if(p==="/api/boss-score"){let m=await meta(env.DB);if(m.phase!=='boss')return json({error:"Bukan Final Boss."},400);let team=String(b.team||"");if(!TEAM_CODES.includes(team))return json({error:"Team tidak sah."},400);let points=Math.max(0,Math.min(250,Number(b.points||0))),notes=String(b.notes||"").slice(0,200);await env.DB.batch([env.DB.prepare(`INSERT INTO boss_scores(boss_index,team,points,notes,timestamp) VALUES(?,?,?,?,?)`).bind(m.item_index,team,points,notes,now()),env.DB.prepare(`UPDATE teams SET xp=xp+?,coins=coins+? WHERE team=?`).bind(points,Math.floor(points/25),team),env.DB.prepare(`UPDATE app_state SET last_event=? WHERE id=1`).bind(`👹 BOSS Team ${team} +${points}`).run()]);return json(await state(env.DB))}
if(p==="/api/attack"){let pid=String(b.player_id||""),pl=await env.DB.prepare(`SELECT * FROM players WHERE id=?`).bind(pid).first(),target=String(b.target||"");if(!pl||!TEAM_CODES.includes(target)||target===pl.team)return json({error:"Target tidak sah."},400);let r=await env.DB.prepare(`UPDATE teams SET xp=xp-50 WHERE team=? AND xp>=50`).bind(pl.team).run();if(!Number(r.meta?.changes))return json({error:"Perlu 50 XP untuk attack."},409);await env.DB.prepare(`UPDATE teams SET hp=MAX(0,hp-100) WHERE team=?`).bind(target).run();await env.DB.prepare(`UPDATE app_state SET last_event=? WHERE id=1`).bind(`⚔️ Team ${pl.team} ATTACK Team ${target} — -100 HP`).run();return json(await state(env.DB))}
if(p==="/api/timer"){let sec=Math.max(0,Math.min(600,+b.seconds||0));await env.DB.prepare(`UPDATE app_state SET timer_end=?,last_event=? WHERE id=1`).bind(sec?now()+sec:0,`Timer ${sec}s`).run();return json(await state(env.DB))}
if(p==="/api/reset"){await env.DB.batch([env.DB.prepare(`DELETE FROM answers`),env.DB.prepare(`DELETE FROM players`),env.DB.prepare(`DELETE FROM boss_scores`),env.DB.prepare(`UPDATE teams SET hp=1000,xp=0,coins=0`),env.DB.prepare(`UPDATE app_state SET started=0,phase='lobby',mode='MCQ',item_index=0,timer_end=0,last_event='Room reset' WHERE id=1`)]);return json(await state(env.DB))}
return json({error:"bad request"},400)}
export default {fetch:handler};
